{
  "root_causes": [
    {
      "service": "geo",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT CAST(time AS VARCHAR) t, value FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'geo%' ORDER BY time",
          "claim": "geo pod restart counter rose from 0 (normal) to 3 at 03:49 and 6 by 03:52, repeatedly restarting."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, COUNT(*) n, MIN(CAST(time AS VARCHAR)) first_t, MAX(CAST(time AS VARCHAR)) last_t FROM abnormal_traces WHERE service_name='geo' GROUP BY 1,2,3",
          "claim": "geo served only 3 Nearby spans in the abnormal window, all at 03:48:40, versus 695 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, COUNT(*) n, ROUND(AVG(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' GROUP BY 1,2,3",
          "claim": "search's calls to geo all return Error in about 0.02 ms (822 calls), versus normal successful calls averaging 0.42 ms."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, level, message, COUNT(*) n FROM abnormal_logs WHERE message = 'Failed to get nearby hotels from geo service' GROUP BY 1,2,3",
          "claim": "search logs 1038 ERROR entries 'Failed to get nearby hotels from geo service' once geo goes away."
        },
        {
          "kind": "log",
          "sql": "SELECT SUBSTR(message,1,400) m FROM abnormal_logs WHERE message LIKE '%Container hotel-reserv-geo definition changed, will be restarted%' LIMIT 1",
          "claim": "kubelet event at 03:48:40 says the hotel-reserv-geo container definition changed and will be restarted."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "geo",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, COUNT(*) n, ROUND(AVG(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby') OR (service_name='search' AND span_name='geo.Geo/Nearby') GROUP BY 1,2,3,4",
          "claim": "search.Search/Nearby server spans all turn Error (822) right after its geo.Geo/Nearby client calls fail."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, COUNT(*) n, ROUND(AVG(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby') GROUP BY 1,2",
          "claim": "frontend HTTP /hotels returns Error for 770 requests, all of which called the failing search.Search/Nearby."
        }
      ]
    }
  ]
}
